-- stg_mp_packages_transferred_altpull: part 1 of 1, 9891 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mp_packages_transferred_altpull (
  destination_license text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mp_packages_transferred_altpull enable row level security;
drop policy if exists stg_mp_packages_transferred_altpull_read on public.stg_mp_packages_transferred_altpull;
create policy stg_mp_packages_transferred_altpull_read on public.stg_mp_packages_transferred_altpull for select to authenticated using (true);
